describe('File Upload Functionality', () => {
    beforeEach(() => {
        cy.visit('/upload'); // Replace with the actual URL of the upload page
    });

    it('should display the file name and size after selecting a valid file', () => {
        const fileName = 'example.txt';
        const fileSize = '1 KB'; // Adjust based on the actual file size

        cy.fixture(fileName).then(fileContent => {
            cy.get('input[type="file"]').attachFile(fileName);
            cy.get('.file-info').should('be.visible');
            cy.get('.file-name').should('contain.text', fileName);
            cy.get('.file-size').should('contain.text', fileSize);
        });
    });

    it('should not display file info when no file is selected', () => {
        cy.get('.file-info').should('not.exist');
    });
});
